{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "STATUS_A.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "prevista para D40",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia está prevista para D43."
        },
        {
          "citacao": "disponibilidade do protótipo para D25",
          "motivo": "valor_divergente",
          "correto_seria": "A disponibilidade do protótipo é D28."
        },
        {
          "citacao": "entrega da GearWorks em D20",
          "motivo": "valor_divergente",
          "correto_seria": "A entrega da GearWorks é em D23."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "MotorTech entrega o motor em D18, com 2 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MotorTech entrega em D18, com 5 dias de folga."
        },
        {
          "citacao": "GearWorks entrega o redutor em D20, sem folga",
          "motivo": "valor_divergente",
          "correto_seria": "A GearWorks entrega em D23, sem folga."
        },
        {
          "citacao": "MetalForm entrega carcaça, eixo, rolamento e vedação em D17, com 3 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm entrega em D17, com 6 dias de folga."
        },
        {
          "citacao": "SensePro entrega o sensor em D16, com 4 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A SensePro entrega em D16, com 7 dias de folga."
        },
        {
          "citacao": "entrega em D19, com apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "O fornecedor da placa de controle e do chicote entrega em D19, com 4 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a montagem do protótipo, de D20 a D25",
          "motivo": "valor_divergente",
          "correto_seria": "A montagem do protótipo ocorre de D23 a D28."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.TESTES",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todos os testes começam em D25",
          "motivo": "valor_divergente",
          "correto_seria": "Todos os testes começam em D28."
        },
        {
          "citacao": "carga, 4 dias, até D29",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de carga dura 4 dias, até D32."
        },
        {
          "citacao": "térmico, 6 dias, até D31",
          "motivo": "valor_divergente",
          "correto_seria": "O teste térmico dura 6 dias, até D34."
        },
        {
          "citacao": "vida, 10 dias, até D35",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vida dura 10 dias, até D38."
        },
        {
          "citacao": "vedação, 3 dias, até D28",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vedação dura 3 dias, até D31."
        },
        {
          "citacao": "compatibilidade eletromagnética, 5 dias, até D30",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de compatibilidade eletromagnética dura 5 dias, até D33."
        },
        {
          "citacao": "concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D38."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "O orçamento total é de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O custo total atualizado é de R$ 152.900,00, incluindo R$ 900,00 por três dias além de D40."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "As avaliações sobre a equipe são opiniões; a revisão planejada por Ana não é verificável a partir do estado do projeto."
    },
    {
      "trecho_id": "STATUS_B.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "dentro do cronograma",
          "motivo": "premissa_alterada",
          "correto_seria": "O cronograma da linha de base foi estendido: a liberação passa de D40 para D43."
        },
        {
          "citacao": "sem risco no caminho crítico",
          "motivo": "premissa_alterada",
          "correto_seria": "A entrega da GearWorks em D23 afeta o caminho crítico e desloca a liberação para D43."
        },
        {
          "citacao": "fim da sexta semana",
          "motivo": "valor_divergente",
          "correto_seria": "A liberação ocorre no início da sétima semana, em D43."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todas as entregas de fornecedores estão programadas para a terceira semana",
          "motivo": "valor_divergente",
          "correto_seria": "A entrega do redutor é em D23, no início da quarta semana; as demais entregas de fornecedores permanecem na terceira semana."
        },
        {
          "citacao": "no fim dessa semana",
          "motivo": "valor_divergente",
          "correto_seria": "O redutor é entregue em D23, no início da quarta semana."
        },
        {
          "citacao": "dois dias antes dele",
          "motivo": "valor_divergente",
          "correto_seria": "O motor é entregue cinco dias antes do redutor."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.ENGENHARIA",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "As datas e a referência à montagem durante a quarta semana continuam compatíveis com o cronograma atualizado."
    },
    {
      "trecho_id": "STATUS_B.TESTES",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "no fim da quarta semana",
          "motivo": "valor_divergente",
          "correto_seria": "A bateria de testes começa em D28, no início da quinta semana."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "sem desvios em relação ao total aprovado de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O custo atualizado é R$ 152.900,00, R$ 900,00 acima do total aprovado."
        },
        {
          "citacao": "nem de gestão",
          "motivo": "valor_divergente",
          "correto_seria": "Há três dias extras de gestão além de D40, com custo adicional de R$ 900,00."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "A avaliação sobre o clima da equipe é uma opinião; a informação sobre o projeto Beta não se aplica ao Alfa."
    }
  ]
}
